div.script:
(function () {
    // Counter animation
    function animateCounter(el) {
        const target = parseFloat(el.dataset.target) || 0;
        const suffix = el.dataset.suffix || '';
        const duration = 1600;
        const step = 16;
        const increment = target / (duration / step);
        let current = 0;
        const timer = setInterval(function () {
            current = Math.min(current + increment, target);
            el.textContent = Math.round(current).toLocaleString('en-IN') + suffix;
            if (current >= target) clearInterval(timer);
        }, step);
    }

    // IntersectionObserver for counters and fade-in
    const io = new IntersectionObserver(function (entries) {
        entries.forEach(function (e) {
            if (!e.isIntersecting) return;
            io.unobserve(e.target);
            if (e.target.classList.contains('edu-count-up')) {
                animateCounter(e.target);
            }
            if (e.target.classList.contains('edu-anim-up')) {
                e.target.classList.add('is-visible');
            }
        });
    }, { threshold: 0.25 });

    document.querySelectorAll('.edu-count-up, .edu-anim-up').forEach(function (el) {
        io.observe(el);
    });
})();
